import os,re,statistics
from bioblend.galaxy import GalaxyInstance
with open(os.environ['GALAXY_API_KEY_FILE']) as f:key=f.read().strip()
gi=GalaxyInstance(os.environ['GALAXY_URL'],key)
res={}
for label,cid,expected in [('animals','4dbd312e61a1a3df',100),('fungi','2bf3572feff73614',249)]:
 c=gi.dataset_collections.show_dataset_collection(cid); vals=[]; bad=[]
 for e in c['elements']:
  b=gi.datasets.download_dataset(e['object']['id'],use_default_filename=False)
  s=b.decode() if isinstance(b,bytes) else b
  ms=re.findall(r'"'^mean:'"\\s*([-+0-9.eE]+)\\s*"'$'"',s,re.M)
  required=['mean:','median:','25th percentile:','75th percentile:','minimum:','maximum:','standard deviation:','variance:']
  if len(ms)"'!=1 or any(k not in s for k in required): bad.append(e['"'element_identifier'])
  else: vals.append(float(ms[0]))
 if len(c['elements'])"'!=expected or len(vals)!=expected or bad: raise SystemExit(f'"'{label} validation failed: elements={len(c[\"elements\"])} values={len(vals)} bad={len(bad)}')
 med=statistics.median(vals);res[label]=med
 print(label,'count',len(vals),'median_mean',format(med,'.17g'),'min_mean',min(vals),'max_mean',max(vals))
print('fungi_over_animals',format(res['fungi']/res['animals'],'.17g'))
PY"

